const RELEASE_PREFIX_RE=/^\d{4}\./;function compareValidSemver(e,t){const n=parse(e);const r=parse(t);return n&&r?n.compare(r):null}function isOpenClawCorrectionSemver(e){return e.prerelease.length===1&&typeof e.prerelease[0]===`number`}function toOpenClawComparableVersion(e){if(isOpenClawCorrectionSemver(e))return`${e.major}.${e.minor}.${e.patch}+${e.prerelease[0]}`;return e.version}function compareOpenClawSemver(e,t){return compareBuild(toOpenClawComparableVersion(e),toOpenClawComparableVersion(t))}function parseOpenClawReleaseVersion(e){const t=e.trim();const n=RELEASE_PREFIX_RE.test(t)?parse(t):null;if(!n||n.build.length>0)return null;if(n.minor<1||n.minor>12||n.patch<1)return null;const[r,i]=n.prerelease;const a=n.prerelease.length===0;const o=isOpenClawCorrectionSemver(n)&&typeof r===`number`&&r>0;const s=n.prerelease.length===2&&(r===`alpha`||r===`beta`)&&typeof i===`number`&&i>0;if(!a&&!o&&!s)return null;return n}function normalizeLegacyDotBetaVersion(e){const t=e.trim();const n=/^([vV]?[0-9]+\.[0-9]+\.[0-9]+)\.beta(?:\.([0-9A-Za-z.-]+))?$/.exec(t);if(!n)return t;const r=n[1];const i=n[2];return i?`${r}-beta.${i}`:`${r}-beta`}export{parseOpenClawReleaseVersion as a,normalizeLegacyDotBetaVersion as i,compareValidSemver as n,isOpenClawCorrectionSemver as r,compareOpenClawSemver as t};